// js
// 労働基準法 art.39(1)–(2): a grant day six months after hire and each year after it, the days by length of service.
const employment = ctx.subject.employment;
const started = get(employment, 'service_started_on', get(employment, 'effective_range.from', null));
const offset = ctx.lookup.service_offset_months;
const months = calendar_completed_months(started, ctx.as_of);
if (months < offset) return 0;
const years = Math.floor((months - offset) / 12);
const grant = add_months(started, offset + years * 12);
const extension = get(employment, 'employee_extension_data', {});
// art.39(1)–(2): attendance below the ratio before a grant day leaves that year without a grant; HR records it on the day.
if (get(employment, 'events', []).some((event) => event.kind === 'ATTENDANCE_BELOW_RATIO' && event.on === grant)) return 0;
// art.39(3) with 施行規則 art.24の3: below the weekly hours and days, the table for the days scheduled.
const terms = get(employment, 'terms', {});
const hours = Number(get(terms, 'normal_hours_per_week', 0));
const perWeek = Number(get(terms, 'normal_days_per_week', ctx.lookup.full_time_days_per_week));
const full = perWeek >= ctx.lookup.full_time_days_per_week;
if (hours > 0 && hours < ctx.lookup.full_time_weekly_hours && !full) {
	const row = ctx.lookup.grant_days_by_normal_days_per_week.filter((item) => item.normal_days_per_week === perWeek && item.service_year <= years + 1).at(-1);
	return get(row ?? {}, 'days', 0);
}
return ctx.lookup.service_bands.filter((band) => band.service_months <= months).reduce((days, band) => Math.max(days, band.days), 0);

// js
// 育児・介護休業法 art.16の2(1): days a business year by the children in third year of elementary school or below; 学校教育法 art.17(1): that is a child not yet the limiting age on the 1 April the school year opens.
const month = Number(ctx.as_of.substring(5, 7));
const opens = add_months(month_start(ctx.as_of), -((month + 12 - ctx.lookup.fiscal_year_start_month) % 12));
const children = get(ctx.subject.employment, 'events', []).filter((event) => event.kind === 'CHILD_BIRTH' && event.on <= ctx.as_of && get(event, 'ended_on', ctx.as_of) >= ctx.as_of && age_on(event.on, opens) < ctx.lookup.school_age_limit_years);
return children.length === 0 ? 0 : children.length === 1 ? ctx.lookup.days_one_child : ctx.lookup.days_two_or_more;

// js
// 育児・介護休業法 art.16の5(1): days a business year by the family members in need of care the worker looks after.
const recipients = Number(get(ctx.subject.employment, 'employee_extension_data.family_care_recipients', 0));
return recipients === 0 ? 0 : recipients >= ctx.lookup.recipient_threshold ? ctx.lookup.days_two_or_more : ctx.lookup.days_one_recipient;
